   242→                          backgroundColor: '#1e3a5f',
   243→                        },
   244→                        {
   245→                          label: 'Rapporte',
   246→                          data: chartData.map(d => d.reports),
   247→                          backgroundColor: '#c8102e',
   248→                        },
   249→                      ],
   250→                    }}
   251→                    options={{
   252→                      responsive: true,
   253→                      maintainAspectRatio: false,
   254→                      plugins: { legend: { position: 'bottom' } },
   255→                      scales: {
