   257→                        y: { beginAtZero: true },
   258→                      },
   259→                    }}
   260→                  />
   261→                </div>
   262→              </div>
   263→
   264→              {/* Pie chart: Rapporte distribution */}
   265→              <div ref={pieCardRef} className="bg-white rounded-xl shadow p-3 sm:p-4">
   266→                <div className="flex items-center justify-between mb-2 sm:mb-3">
   267→                  <h2 className="text-xs sm:text-sm font-semibold text-[#1e3a5f]">
   268→                    Rapporte Verteilung nach Bundesland / Land
   269→                  </h2>
   270→                  <button
   271→                    onClick={() => downloadChart(pieCardRef, `BOS-ARSA_Verteilung_${exercise.date}.png`)}
   272→                    className="text-xs text-gray-400 hover:text-blue-600 flex-shrink-0 ml-2"
   273→                    title="Grafik als PNG herunterladen"
   274→                    data-no-export="true"
   275→                  >
   276→                    Download
   277→                  </button>
   278→                </div>
   279→                <div className="h-48 sm:h-[350px] flex items-center justify-center">
   280→                  <Pie
