   286→                        backgroundColor: [
   287→                          '#1e3a5f', '#c8102e', '#d97706', '#0d6efd', '#198754',
   288→                          '#6f42c1', '#fd7e14', '#20c997', '#0dcaf0', '#6c757d',
   289→                          '#2c5282', '#e8a317', '#c70039', '#4361ee', '#2d6a4f',
   290→                          '#9b59b6', '#e67e22', '#1abc9c', '#3498db', '#95a5a6',
   291→                        ],
   292→                      }],
   293→                    }}
   294→                    options={{
   295→                      responsive: true,
   296→                      maintainAspectRatio: false,
   297→                      plugins: {
   298→                        legend: { position: 'right', labels: { font: { size: 10 } } },
   299→                      },
   300→                    }}
   301→                  />
   302→                </div>
   303→              </div>
   304→            </div>
   305→          ) : null;
   306→          })()}
   307→
   308→          {/* Bundesland table (when no bezirk data) */}
   309→          {stats.bezirkStats.length === 0 && stats.blStats.length > 0 && (
   310→            <div className="bg-white rounded-xl shadow overflow-hidden">
